<script setup lang="ts">
import { ArrowRight, CheckCircle2, History, RefreshCw, Sparkles } from 'lucide-vue-next'
import { computed, watch } from 'vue'
import WritingEvidenceInspector from './WritingEvidenceInspector.vue'
import type { ProductWritingCluster, ProductWritingClusterDetail, ProductWritingClusterOverview } from '@/types/product'

const props = defineProps<{ overview: ProductWritingClusterOverview; detail: ProductWritingClusterDetail | null; activeClusterId: string | null; filter: string; loading: boolean; detailLoading: boolean; saving: boolean }>()
const emit = defineEmits<{ open: [clusterId: string]; status: [cluster: ProductWritingCluster, status: ProductWritingCluster['status']]; filter: [value: string]; refresh: []; replay: []; continue: []; 'load-more': [] }>()
const selectedCluster = computed(() => props.overview.clusters.find((cluster) => cluster.id === props.activeClusterId) ?? props.overview.clusters[0] ?? null)

watch(() => props.overview.clusters, (clusters) => {
  if (!props.activeClusterId && clusters[0]) emit('open', clusters[0].id)
}, { immediate: true })
</script>

<template>
  <section class="curation-shell" aria-labelledby="curation-title">
    <header class="curation-header"><div><span class="eyebrow">01 · Evidence map</span><h2 id="curation-title">确认一条完整的证据链。</h2><p>左侧选择一个聚类，右侧确认它是否值得写并检查对应的原始记录。原始记录保持不变。</p></div><div class="curation-header-actions"><button class="secondary-button replay-button" type="button" title="从实践事件中补齐缺失记录" :disabled="loading" @click="emit('replay')"><History :size="13" aria-hidden="true" />重放记录</button><button class="icon-button" type="button" title="重新整理证据地图" aria-label="重新整理证据地图" :disabled="loading" @click="emit('refresh')"><RefreshCw :size="14" aria-hidden="true" /></button></div></header>
    <div class="curation-progress"><div><strong>{{ overview.acceptedCount }} / {{ overview.totalCount }}</strong><span>个聚类已确认</span></div><div class="progress-track" aria-hidden="true"><span :style="{ width: `${overview.totalCount ? (overview.acceptedCount / overview.totalCount) * 100 : 0}%` }" /></div><span class="progress-note">{{ overview.canGenerateOutline ? '核心证据已齐，可以生成大纲。' : '至少确认问题、证据和验证三个聚类。' }}</span><button v-if="overview.canGenerateOutline" class="primary-button" type="button" @click="emit('continue')">进入大纲 <ArrowRight :size="13" aria-hidden="true" /></button></div>
    <div v-if="overview.curation.status === 'queued' || overview.curation.status === 'running'" class="curation-notice"><Sparkles :size="13" aria-hidden="true" />模型正在润色卡片摘要，当前规则摘要已经可以确认。</div>
    <div v-else-if="overview.curation.status === 'failed'" class="curation-notice muted"><Sparkles :size="13" aria-hidden="true" />模型摘要暂不可用，当前内容来自可追溯的实验记录。</div>
    <div class="curation-body">
      <nav class="cluster-nav" aria-label="证据聚类"><div class="nav-heading"><span>证据聚类</span><small>{{ overview.totalCount }} 个判断簇</small></div><button v-for="cluster in overview.clusters" :key="cluster.id" type="button" :class="{ active: selectedCluster?.id === cluster.id, accepted: cluster.status === 'accepted', rejected: cluster.status === 'rejected' }" @click="emit('open', cluster.id)"><span class="nav-marker"><CheckCircle2 v-if="cluster.status === 'accepted'" :size="13" aria-hidden="true" /><span v-else>{{ String(cluster.position).padStart(2, '0') }}</span></span><span><strong>{{ cluster.title }}</strong><small>{{ cluster.status === 'accepted' ? '已纳入' : cluster.status === 'rejected' ? '暂不纳入' : '待确认' }} · {{ cluster.memberCount }} 条</small></span></button></nav>
      <WritingEvidenceInspector :cluster="selectedCluster" :detail="detail" :loading="detailLoading" :filter="filter" :saving="saving" @accept="selectedCluster && emit('status', selectedCluster, 'accepted')" @reject="selectedCluster && emit('status', selectedCluster, 'rejected')" @reset="selectedCluster && emit('status', selectedCluster, 'pending')" @update:filter="emit('filter', $event)" @load-more="emit('load-more')" />
    </div>
  </section>
</template>

<style scoped>
