.curation-header { display: flex; justify-content: space-between; gap: 16px; padding: 18px 20px 15px; border-bottom: 1px solid var(--line); }.curation-header h2 { margin: 6px 0 0; color: var(--ink); font: 400 24px/1.2 var(--serif); }.curation-header p { max-width: 700px; margin: 7px 0 0; color: var(--muted); font-size: 11px; line-height: 1.55; }.curation-header-actions { display: flex; align-items: start; gap: 8px; }.replay-button { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
