.curation-body { display: grid; grid-template-columns: 245px minmax(0, 1fr); height: min(680px, calc(100vh - 310px)); min-height: 520px; overflow: hidden; }.cluster-nav { display: grid; align-content: start; gap: 1px; overflow-y: auto; padding: 10px 0; border-right: 1px solid var(--line); background: var(--paper-muted); }.nav-heading { display: flex; justify-content: space-between; gap: 8px; padding: 5px 14px 10px; color: var(--ink); font-size: 10px; }.nav-heading small { color: var(--muted); font: 8px var(--mono); }.cluster-nav button { display: grid; grid-template-columns: 25px minmax(0, 1fr); gap: 8px; align-items: center; padding: 11px 14px; border: 0; border-left: 2px solid transparent; background: transparent; color: var(--muted); text-align: left; cursor: pointer; }.cluster-nav button:hover, .cluster-nav button.active { border-left-color: var(--blue); background: #fff; color: var(--blue); }.cluster-nav button.accepted { color: var(--green); }.cluster-nav button.rejected { opacity: .65; }.nav-marker { display: grid; place-items: center; width: 23px; height: 23px; border: 1px solid currentColor; font: 9px var(--mono); }.cluster-nav strong, .cluster-nav small { display: block; }.cluster-nav strong { overflow: hidden; font-size: 11px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }.cluster-nav small { margin-top: 3px; color: var(--muted); font: 8px var(--mono); }.evidence-inspector { min-height: 0; overflow: hidden; }
